/* Display preview only. Multiline instructions are generated by /api/spell. */
(function(root){
'use strict';
root.SpellMulti={prepare(raw,{lines=2,center=true,compressSpaces=true}={}){
 if(![2,3,4].includes(lines))throw Error('Chọn 2, 3 hoặc 4 dòng.');
 const source=raw.replace(/\r\n?/g,'\n').split('\n');
 if(source.length>lines)throw Error(`Bạn đang nhập ${source.length} dòng. Chọn chế độ đủ số dòng hoặc bỏ bớt dòng xuống hàng.`);
 while(source.length<lines)source.push('');
 const input=source.map(t=>root.Spell.parseText(t));
 return {spacing:input.map(a=>root.Spell.fitInput(a,{compressSpaces})),displayLines:input.map((a,i)=>{try{return root.Spell.prepareLine(a,{center,compressSpaces});}catch(e){throw Error(`Dòng ${i+1}: ${e.message}`);}})};
}};
})(globalThis);
